<script lang="ts">
	import { onMount } from 'svelte';
	import { page } from '$app/state';
	import { supabase } from '#lib/supabase';
	import { PROJECT_STATUSES, formatMoney, nextStatus, statusInfo } from '#lib/workflow';
	import { ArrowLeft, Boxes, CalendarDays, CheckCircle2, ClipboardList, Download, Factory, GlassWater, Ruler, Save, Scissors, UserRound } from '@lucide/svelte';
	let project = $state<any>(null), drawing = $state<any>(null), loading = $state(true), error = $state(''), saving = $state(false);
	let active = $state<'summary'|'materials'|'documents'|'planning'>('summary');
	let montageDate = $state(''), montageTeam = $state('Montaj Ekibi 1'), note = $state('');
	const key = page.params.key;
	onMount(load);
	async function load() {
		loading = true;
		const [projectResult, drawingResult] = await Promise.all([
			supabase.from('cb_records').select('*').eq('key', key).eq('kind', 'project').single(),
			supabase.from('cb_records').select('*').eq('kind', 'drawing').eq('deleted', false)
		]);
		if (projectResult.error) { error = projectResult.error.message; loading = false; return; }
		project = projectResult.data;
		drawing = (drawingResult.data || []).find((item:any) => item.data?.project_key === key) || null;
		montageDate = project.data?.montage_date || ''; montageTeam = project.data?.montage_team || 'Montaj Ekibi 1'; note = project.data?.note || ''; loading = false;
	}
	async function update(values: Record<string, unknown>) {
		if (!project) return; saving = true;
		const updated = { ...project.data, ...values, updated_at: new Date().toISOString() };
		const { error: updateError } = await supabase.from('cb_records').update({ data: updated, origin: 'web' }).eq('key', key);
		if (updateError) error = updateError.message; else project = { ...project, data: updated };
		saving = false;
	}
	function production() { return drawing?.data?.production || {}; }
	function cuts() { return production().cuts || drawing?.data?.cuts || []; }
	function accessories() { return production().accessories || drawing?.data?.materials || []; }
	function bars() { return production().bars || drawing?.data?.bars || []; }
</script>
<svelte:head><title>İş Detayı | Tayfun Yapı</title></svelte:head>
{#if loading}<div class="state">İş dosyası yükleniyor...</div>{:else if error}<div class="state error">{error}</div>{:else}
<div class="page">
	<header><a href="/projects" title="İşlere dön"><ArrowLeft size={20}/></a><div><span class="eyebrow">İŞ DOSYASI · {key.toUpperCase()}</span><h1>{project.data?.name || 'Adsız iş'}</h1><p>{project.data?.customer || 'Müşteri seçilmedi'}</p></div><div class="header-actions"><span class="status" style={`--status:${statusInfo(project.data?.status).color}`}>{statusInfo(project.data?.status).label}</span><button onclick={() => update({ status: nextStatus(project.data?.status).code })} disabled={saving || project.data?.status === 'TESLIM'}><CheckCircle2 size={17}/>{project.data?.status === 'TESLIM' ? 'Tamamlandı' : `${nextStatus(project.data?.status).label} yap`}</button></div></header>
	<div class="flow">{#each PROJECT_STATUSES as item, index}<button class:done={PROJECT_STATUSES.findIndex(s => s.code === project.data?.status) >= index} class:current={item.code === project.data?.status} onclick={() => update({status:item.code})}><i></i><span>{item.label}</span></button>{/each}</div>
	<nav><button class:active={active==='summary'} onclick={() => active='summary'}><ClipboardList size={17}/>Özet</button><button class:active={active==='materials'} onclick={() => active='materials'}><Boxes size={17}/>Malzemeler</button><button class:active={active==='planning'} onclick={() => active='planning'}><CalendarDays size={17}/>Montaj</button><button class:active={active==='documents'} onclick={() => active='documents'}><Download size={17}/>Belgeler</button></nav>
	{#if active==='summary'}
		<section class="overview"><div class="hero"><div><span>SİSTEM</span><strong>{drawing?.data?.production?.system?.name || drawing?.data?.system || 'Hesap bekliyor'}</strong><small>{drawing?.data?.props?.color || '-'}</small></div><div><span>ÖLÇÜ</span><strong>{drawing?.data?.props?.width || '-'} × {drawing?.data?.props?.height || '-'} mm</strong><small>{production().panelCount || '-'} kanat</small></div><div><span>ALAN</span><strong>{Number(drawing?.data?.area || 0).toFixed(2)} m²</strong><small>{production().glassArea || 0} m² cam</small></div><div class="money"><span>İŞ TUTARI</span><strong>{formatMoney(drawing?.data?.price)}</strong><small>Satış toplamı</small></div></div><div class="columns"><article><h2><UserRound size={18}/>Müşteri ve iş</h2><dl><dt>Müşteri</dt><dd>{project.data?.customer || '-'}</dd><dt>Oluşturma</dt><dd>{new Date(project.data?.created_at || project.updated_at).toLocaleDateString('tr-TR')}</dd><dt>Son durum</dt><dd>{statusInfo(project.data?.status).label}</dd><dt>Montaj tarihi</dt><dd>{project.data?.montage_date ? new Date(project.data.montage_date).toLocaleDateString('tr-TR') : 'Planlanmadı'}</dd></dl></article><article><h2><Factory size={18}/>Üretim özeti</h2><dl><dt>Profil</dt><dd>{production().profileMeters || 0} m</dd><dt>Standart boy</dt><dd>{production().stockBarCount || bars().length || 0} adet</dd><dt>Kesim verimi</dt><dd>%{production().efficiency || 0}</dd><dt>Toplam fire</dt><dd>{((production().totalWaste || 0)/1000).toFixed(2)} m</dd></dl></article></div></section>
	{:else if active==='materials'}
		<section class="materials"><div class="material-card"><h2><GlassWater size={19}/>Cam siparişi</h2>{#if production().glassWidth}<strong>{production().panelCount} adet · {production().glassWidth} × {production().glassHeight} mm</strong><span>{drawing?.data?.props?.glassType} · {production().glassArea} m²</span>{:else}<p>Cam hesabı bulunamadı.</p>{/if}</div><div class="material-card"><h2><Boxes size={19}/>Aksesuarlar</h2>{#each accessories() as item}<div class="line"><span>{item.name}</span><strong>{item.quantity} {item.unit}</strong></div>{:else}<p>Aksesuar kaydı yok.</p>{/each}</div><div class="wide material-card"><h2><Scissors size={19}/>Profil kesim listesi</h2><div class="table"><div class="tr head"><span>Kod</span><span>Profil / görev</span><span>Boy</span><span>Adet</span></div>{#each cuts() as cut}<div class="tr"><code>{cut.profileCode || cut.profile_code}</code><span><strong>{cut.profileName || cut.profile_name}</strong><small>{cut.role}</small></span><span>{cut.length || cut.length_mm} mm</span><strong>{cut.quantity}</strong></div>{:else}<p>Kesim hesabı bulunamadı.</p>{/each}</div></div><div class="wide material-card"><h2><Ruler size={19}/>Boy optimizasyonu</h2><div class="bar-grid">{#each bars() as bar}<div><span>{bar.profileCode || bar.profile_code} · Boy {bar.barNo || bar.bar_no}</span><strong>%{bar.efficiency} verim · {bar.waste || bar.waste_mm} mm fire</strong></div>{:else}<p>Boy planı bulunamadı.</p>{/each}</div></div></section>
	{:else if active==='planning'}
		<section class="planning"><div><CalendarDays size={36}/><h2>Montaj planı</h2><p>Tarih ve ekibi belirlediğinizde iş Montaj Planı ekranına düşer.</p></div><form onsubmit={(e) => {e.preventDefault(); update({montage_date:montageDate,montage_team:montageTeam,note,status:'MONTAJ_PLANLANDI'})}}><label>Montaj tarihi<input type="date" bind:value={montageDate}/></label><label>Montaj ekibi<select bind:value={montageTeam}><option>Montaj Ekibi 1</option><option>Montaj Ekibi 2</option><option>Servis Ekibi</option></select></label><label class="wide">Montaj notu<textarea bind:value={note} placeholder="Adres tarifi, eksik malzeme, müşteri notu..."></textarea></label><button disabled={saving}><Save size={17}/>{saving?'Kaydediliyor':'Montajı planla'}</button></form></section>
	{:else}
		<section class="documents"><a href="/teklif"><Download size={22}/><strong>Teklif ve Sözleşme</strong><span>Fiyat, ödeme ve imza alanları</span></a><button onclick={() => window.print()}><Scissors size={22}/><strong>Kesim Listesi</strong><span>Profil ve boy yerleşimi</span></button><button onclick={() => window.print()}><GlassWater size={22}/><strong>Cam Siparişi</strong><span>Cam ölçüleri ve toplam m²</span></button><button onclick={() => window.print()}><Factory size={22}/><strong>İmalat Formu</strong><span>Atölye üretim dosyası</span></button></section>
	{/if}
</div>{/if}
<style>
	.state{padding:50px;text-align:center}.state.error{color:#b91c1c}.page{max-width:1420px;margin:auto;padding:26px 30px 60px}header{display:flex;align-items:center;gap:13px}header>a{width:40px;height:40px;display:grid;place-items:center;background:#fff;border:1px solid #dce2e6;border-radius:6px;color:#34414a}header h1{margin:1px 0;font-size:25px}header p{margin:0;color:#78838d}.eyebrow{font-size:10px;color:#0f7c80;font-weight:800;letter-spacing:.8px}.header-actions{margin-left:auto;display:flex;align-items:center;gap:9px}.status{padding:7px 10px;background:color-mix(in srgb,var(--status) 12%,white);color:var(--status);border-radius:5px;font-size:11px;font-weight:800}.header-actions button,.planning button{height:39px;border:0;border-radius:5px;background:#0f7c80;color:#fff;padding:0 13px;display:flex;align-items:center;gap:7px;font-weight:800;cursor:pointer}.flow{display:grid;grid-template-columns:repeat(7,1fr);margin:23px 0 16px}.flow button{position:relative;border:0;background:none;color:#8b96a0;font-size:10px;padding:24px 2px 0;cursor:pointer}.flow button:before{content:'';position:absolute;top:7px;left:0;right:0;height:3px;background:#dce2e6}.flow button:first-child:before{left:50%}.flow button:last-child:before{right:50%}.flow i{position:absolute;top:2px;left:calc(50% - 7px);width:14px;height:14px;border:3px solid #dce2e6;background:#f4f6f8;border-radius:50%;z-index:1}.flow button.done:before{background:#59aaa7}.flow button.done i{border-color:#0f8b8d;background:#0f8b8d}.flow button.current{color:#0f6f72;font-weight:800}nav{display:flex;gap:3px;border-bottom:1px solid #dce2e6;margin-bottom:14px}nav button{height:44px;padding:0 16px;display:flex;align-items:center;gap:7px;border:0;border-bottom:3px solid transparent;background:transparent;color:#68747f;font-weight:700;cursor:pointer}nav button.active{color:#0f7c80;border-bottom-color:#0f7c80}.hero{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.hero>div,.columns article,.material-card,.planning,.documents>*{background:#fff;border:1px solid #dde3e7;border-radius:7px}.hero>div{padding:15px}.hero span,.hero strong,.hero small{display:block}.hero span{font-size:9px;color:#7e8993}.hero strong{font-size:17px;margin:4px 0}.hero small{color:#78838d}.hero .money{background:#173f49}.hero .money span,.hero .money strong,.hero .money small{color:#fff}.columns{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.columns article{padding:17px}.columns h2,.material-card h2{font-size:14px;margin:0 0 13px;display:flex;align-items:center;gap:7px}dl{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:0}dt{color:#7d8993}dd{margin:0;text-align:right;font-weight:700}.materials{display:grid;grid-template-columns:1fr 1fr;gap:10px}.material-card{padding:17px}.material-card>strong,.material-card>span{display:block}.material-card>span{margin-top:4px;color:#78838d}.wide{grid-column:1/-1}.line{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #edf0f2}.line:last-child{border:0}.table .tr{display:grid;grid-template-columns:120px 1fr 120px 70px;gap:10px;padding:9px;border-bottom:1px solid #edf0f2;align-items:center}.tr.head{font-size:10px;background:#f6f8f9;color:#75818b;font-weight:800}.tr small,.tr strong{display:block}.tr small{color:#8a949c}.tr code{color:#0f7c80;font-weight:800}.bar-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.bar-grid>div{display:flex;justify-content:space-between;padding:10px;background:#f6f8f9;border-radius:5px}.planning{display:grid;grid-template-columns:300px 1fr;padding:24px;gap:30px}.planning>div{color:#0f7c80}.planning h2{color:#1f2933;margin:9px 0 3px}.planning p{color:#78838d}.planning form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.planning label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:700}.planning input,.planning select,.planning textarea{border:1px solid #d6dde2;border-radius:5px;padding:10px;font:inherit}.planning textarea{min-height:80px;resize:vertical}.planning .wide{grid-column:1/-1}.planning button{justify-self:end;grid-column:1/-1}.documents{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.documents>*{padding:22px;text-align:left;color:#0f7c80;text-decoration:none;cursor:pointer}.documents button{font:inherit}.documents strong,.documents span{display:block;color:#27333c}.documents strong{margin-top:18px}.documents span{font-size:11px;color:#7b8791;margin-top:4px}
	@media(max-width:900px){.hero{grid-template-columns:1fr 1fr}.documents{grid-template-columns:1fr 1fr}.planning{grid-template-columns:1fr}.flow span{display:none}.materials{grid-template-columns:1fr}.wide{grid-column:auto}.bar-grid{grid-template-columns:1fr}}
	@media(max-width:650px){.page{padding:16px 12px 90px}header{align-items:flex-start;flex-wrap:wrap}.header-actions{width:100%;margin:5px 0 0 53px}.header-actions button{flex:1;justify-content:center}.flow{margin-top:15px}.hero{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}nav{overflow:auto;margin:0 -12px 14px;padding:0 8px}.table{overflow:auto}.table .tr{min-width:620px}.planning{padding:16px}.planning form{grid-template-columns:1fr}.planning .wide,.planning button{grid-column:auto}.documents{grid-template-columns:1fr 1fr}.documents>*{padding:16px}}
</style>
